# Analyze each changed pair to find minimal edits
inputs = ['bkcf', 'ceccw', 'ic', 'xuuyg', 'jdj']
outputs = ['bkbufjf', 'bufjebufjbufjw', 'ibufj', 'xdbdbyg', 'jdj']

# Let's look at each changed pair individually
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Pair {i}: '{inp}' -> '{outp}'")

        # Find differences character by character
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))

        # Check if one string is longer
        if len(inp) > len(outp):
            for j in range(min_len, len(inp)):
                diff_positions.append((j, inp[j], None))
        elif len(outp) > len(inp):
            for j in range(min_len, len(outp)):
                diff_positions.append((j, None, outp[j]))

        print(f"  Differences: {diff_positions}")
        print()

